INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300373','SYNFLEET MX 0W-40 205 л','Gulf Western Oil','motor_oil',285150,190100,'Моторные масла','SAE 0W40',205.0,'л',1,'SYNFLEET MX 0W-40 – это линейка премиальных синтетических моторных масел, отвечающих требованиям современных высокомощных дизельных двигателей для тяжелых условиях эксплуатации, включая двигатели, оснащенные устройствами предварительной очистки выхлопных газов: система рециркуляции отработавших газов, система селективного каталитического восстановления, дизельный сажевый фильтр (EGR, SCR, DPF). В продуктах Synfleet MX используется технология присадок, защищающая дизельный двигатель и систему выхлопа в наиболее суровых условиях, в том числе при эксплуатации с многоосными прицепами и вне дорог. Спецификации: SAE 0W-40; API CJ-4/SN; ACEA E9; CUMMINS CES 20081; DETROIT DIESEL 93K218; VOLVO VDS-4; MACK EO-O PREMIUM PLUS; MB 228.31; RENAULT TRUCK RLD-3; CATERPILLAR ECF-3; MAN 3575; JASO DH-2','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
