INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300366','EURO-SYN LV 5W-30 FULL SYN 205 л','Gulf Western Oil','motor_oil',360000,240000,'Моторные масла','SAE 5W30',205.0,'л',1,'EURO-SYN LV 5W-30 – это современное синтетическое моторное масло низкой вязкости для высоконагруженных высокофорсированных дизельных двигателей (UHPD). Продукт обеспечивает исключительную защиту двигателя и в то же время экономию топлива по сравнению с маслами 10W-40 более высокой вязкости. Состав масла EURO-SYN LV 5W-30 соответствует требованиям основных европейских производителей оригинальной техники, включая Mercedes Benz, MAN, MTU, Volvo, Scania и Deutz, а также отвечает высоким требованиям категории ACEA E6/E9 к ключевым эксплуатационным характеристикам европейских дизельных двигателей большой мощности. Спецификации: SAE 5W-30; ACEA E6/E9; API CK-4; JASO DH-2; CUMMINS CES 20086; DEUTZ DQC-IV-10 LA;  MAN M 3677; MB 228.51; MTU TYPE 3.1; RENAULT RLD 4; SCANIA LDF-4; VOLVO VDS 4.5','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
