INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('307250','SUPER LONG LIFE TOP DOG XDO PLUS 5W-40 7 л','Gulf Western Oil','motor_oil',9150,6100,'Моторные масла','SAE 5W40',7.0,'л',1,'Top Dog XDO Plus 5W-40 – это синтетическое моторное масло с увеличенным сроком службы для дизельных двигателей, работающих в тяжелых условиях эксплуатации, которое отвечает самым современным спецификациям. Сочетание синтетической основы и новейших присадок с низким содержанием серы, фосфора и сульфатных зол (low-SAPS) позволяет получить моторное масло с высочайшими эксплуатационными характеристиками и сверхдолгим сроком службы. Спецификации: SAE 5W-40;    ACEA E11; API CK-4/SN; CATERPILLAR ECF-3; CUMMINS CES 20086; DETROIT DIESEL 93K222; JASO DH-2; MAN 3575; MACK EOS 4.5;          MB 228.31; RENAULT TRUCK RLD 4; VOLVO VDS 4.5','7 л',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30009','EURO-SYN LONG DRAIN 10W-40 API CK-4 205 л','Gulf Western Oil','motor_oil',258450,172300,'Моторные масла','SAE 10W40',205.0,'л',1,'Euro-Syn Long Drain – полностью синтетическое моторное масло с исключительно высокими рабочими характеристиками для тяжелых дизельных двигателей. Euro-Syn Long Drain соответствует жестким требованиям европейского стандарта Euro VI, его можно использовать в двигателях, оснащенных сажевыми дизельными фильтрами (DPF) и/или системами селективного восстановления (SCR). Данный продукт идеально подходит для европейских дизельных двигателей с длительными интервалами замены масла –100 000 км и более в зависимости от рекомендаций производителя. Также это отличное масло для смешанных автопарков, поскольку соответствует спецификациям API CK-4 и JASO DH-2 для тяжелых условий эксплуатации, а также большинству современных спецификаций производителей тяжелых дизельных двигателей. Спецификации: ACEA E6/E9/E7/E4; API CK-4; JASO DH-2; CUMMINS CES 20086; CAT ECF-3; DETROIT DIESEL DDC93K222; DEUTZ DQC-IV-10 LA; MACK EOS-4.5; MAN M 3477, M 3271-1;   MB 228.51; MTU TYPE 3.1; RENAULT TRUCK RLD-4; SCANIA LOW ASH; VOLVO VDS 4.5','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
