INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300364','EURO-SYN ME 5W-30 205 л','Gulf Western Oil','motor_oil',321000,214000,'Моторные масла','SAE 5W30',205.0,'л',1,'EURO-SYN ME 5W-30 – это современное полностью синтетическое моторное масло для дизельных двигателей тяжелой техники, способное обеспечить исключительную защиту двигателя в изменчивых условиях эксплуатации. Применение масла EURO-SYN ME 5W-30 способствует более экономному расходу топлива по сравнению с маслами высокой вязкости, имеет увеличенный срок службы при сохранении надежной защиты двигателя от износа. Спецификации: SAE 5W-30; ACEA E4; API CF; SCANIA LDF-3; MB 228.5; MAN M 3277; IVECO STANDARD TFE; VOLVO VDS 2','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
