INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('26356','TOP DOG XDO 5W-30 CI4/SL 205 л','Gulf Western Oil','motor_oil',199350,132900,'Моторные масла','SAE 5W30',205.0,'л',1,'Top Dog XDO 5W-30 – это премиальное высокопроизводительное синтетическое моторное масло на основе современных синтетических базовых компонентов с использованием передовой технологии присадок. Это масло создано с учетом высоких потребностей как современных, так и более ранних дизельных агрегатов и обеспечивает исключительную защиту, чистоту двигателя, а также высокую производительность в широком диапазоне условий эксплуатации. Спецификации: SAE 5W-30; API CI-4/SL; ACEA E7; CATERPILLAR ECF-2; CUMMINS CES 20078, 20077, 20076; DETROIT DFS 93K215; DEUTZ DQC-III-18; JASO DH-1; MACK EO-M, EO-M PLUS; GLOBAL DHD-1; MAN 3275; DTFR 15B110 (MB 228.3); VNU CAT 2; RENAULT RLD-2; MTU TYPE 1; VOLVO VDS-3','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('26354','TOP DOG XDO 5W-30 CI4/SL 18 л','Gulf Western Oil','motor_oil',20550,13700,'Моторные масла',NULL,18.0,'л',1,'Top Dog XDO 5W-30 – это премиальное высокопроизводительное синтетическое моторное масло на основе современных синтетических базовых компонентов с использованием передовой технологии присадок. Это масло создано с учетом высоких потребностей как современных, так и более ранних дизельных агрегатов и обеспечивает исключительную защиту, чистоту двигателя, а также высокую производительность в широком диапазоне условий эксплуатации. Спецификации: SAE 5W-30; API CI-4/SL; ACEA E7; CATERPILLAR ECF-2; CUMMINS CES 20078, 20077, 20076; DETROIT DFS 93K215; DEUTZ DQC-III-18; JASO DH-1; MACK EO-M, EO-M PLUS; GLOBAL DHD-1; MAN 3275; DTFR 15B110 (MB 228.3); VNU CAT 2; RENAULT RLD-2; MTU TYPE 1; VOLVO VDS-3','18 л',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('26256','TOP DOG XDO 5W-40 CI4/SL 205 л','Gulf Western Oil','motor_oil',217800,145200,'Моторные масла','5W-40',205.0,'л',1,'Top Dog XDO 5W-40 – всесезонное синтетическое моторное масло для тяжелых условий эксплуатации, отвечающее требованиям самых последних спецификаций моторного масла. Сочетание базовых масел премиального качества и новейших технологичных присадок позволяет получить моторное масло с наилучшими характеристиками. Top Dog XDO 5W-40 обеспечивает превосходный контроль образования сажи, легкий запуск в холодную погоду, высокий уровень защиты от износа при полной нагрузке и высокой скорости работы. Масло Top Dog XDO 5W-40 разработано для удовлетворения потребностей дизельных двигателей нового поколения с низким уровнем выбросов, работающих на топливе с низким содержанием серы, а также старых двигателей, работающих на дизельном топливе с высоким содержанием серы. Top Dog XDO 5W-40 рекомендуется для высокопроизводительных дизельных и бензиновых двигателей без наддува или с турбонаддувом. Спецификации: SAE 5W-40; API CI-4, CH-4, CG-4/SL; ACEA E7; JASO DH-1; Global DHD-1; Caterpillar ECF-2; Cummins CES 20078; Detroit Diesel 93K215; MAN 3275;                                      Mack EO-N Premium Plus; MB 228.3; MTU Type 1; Volvo VDS-3','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
