INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('304170','TOP DOG XDO 5W-40 CI4/SL 4 л. × 4 шт','Gulf Western Oil','motor_oil',4800,3200,'Моторные масла',NULL,4.0,'л',4,'Top Dog XDO 5W-40 – всесезонное синтетическое моторное масло для тяжелых условий эксплуатации, отвечающее требованиям самых последних спецификаций моторного масла. Сочетание базовых масел премиального качества и новейших технологичных присадок позволяет получить моторное масло с наилучшими характеристиками. Top Dog XDO 5W-40 обеспечивает превосходный контроль образования сажи, легкий запуск в холодную погоду, высокий уровень защиты от износа при полной нагрузке и высокой скорости работы. Масло Top Dog XDO 5W-40 разработано для удовлетворения потребностей дизельных двигателей нового поколения с низким уровнем выбросов, работающих на топливе с низким содержанием серы, а также старых двигателей, работающих на дизельном топливе с высоким содержанием серы. Top Dog XDO 5W-40 рекомендуется для высокопроизводительных дизельных и бензиновых двигателей без наддува или с турбонаддувом. Спецификации: SAE 5W-40; API CI-4, CH-4, CG-4/SL; ACEA E7; JASO DH-1; Global DHD-1; Caterpillar ECF-2; Cummins CES 20078; Detroit Diesel 93K215; MAN 3275;                                      Mack EO-N Premium Plus; MB 228.3; MTU Type 1; Volvo VDS-3','4 л. х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300127B','TOP DOG XDO CI4/SL 1000 л','Gulf Western Oil','motor_oil',0,NULL,'Моторные масла','SAE 10W-30',1000.0,'л',1,'Top Dog® XDO – дизельное моторное масло премиум-класса, созданное по самым современным технологиям производства смазочных материалов. Продукт одобрен Mack Trucks USA и Volvo Sweden для применения во всем мире и официально признан в качестве масла первой производственной заливки. Идеально подходит для смешанных автопарков, где есть автомобили с дизельными двигателями производства США, Европы и Японии. Рекомендовано как для дизельных двигателей, снабженных системой рециркуляции выхлопных газов (EGR), так и более ранних моделей дизельных двигателей без системы рециркуляции выхлопных газов. Top Dog® XDO можно применять в стационарных двигателях, тяжелонагруженной технике для земляных работ и дорожном транспорте, а также в дизельных двигателях легкой коммерческой техники и трансмиссиях с допуском Allison C4. Кроме того, можно использовать в последних моделях бензиновых двигателей, как стационарных, так и в смешанных автопарках.
