INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300388','TOP DOG CNG 10W-40 CK-4/SN 205 л','Gulf Western Oil','motor_oil',198000,132000,'Моторные масла','SAE 10W40',205.0,'л',1,'Top Dog CNG – это высококачественное моторное масло на синтетической основе с диспергирующими и моющими присадками, созданное специально для использования в газовых и дизельных двигателях. Оптимальное содержание противоизносных присадок позволяет удовлетворить повышенные требования к защите от износа как дизельных двигателей, так и двигателей, переоборудованных для работы на природном газе. Особенно рекомендуется для использования в транзитных автобусах, школьных автобусах, грузовиках доставки и других транспортных средствах, оснащенных двигателями Cummins, Detroit Diesel, Volvo или переоборудованными для работы на природном газе. Спецификации: API CK-4/SN; CUMMINS CES 20092; CUMMINS CES 20085; DETROIT DIESEL DDC 93K216; DETROIT DIESEL DFS 93K222; VOLVO VDS 4.5; Рекомендуется для двигателей Yutong, Foton, Sitrak, Shacman, FAW, Howo, JAC, Weichai Power, Yuchai, Yunnei Power.','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('308388','TOP DOG CNG 10W-40 CK-4/SN 18 л','Gulf Western Oil','motor_oil',20400,13600,'Моторные масла',NULL,18.0,'л',1,'Top Dog CNG – это высококачественное моторное масло на синтетической основе с диспергирующими и моющими присадками, созданное специально для использования в газовых и дизельных двигателях. Оптимальное содержание противоизносных присадок позволяет удовлетворить повышенные требования к защите от износа как дизельных двигателей, так и двигателей, переоборудованных для работы на природном газе. Особенно рекомендуется для использования в транзитных автобусах, школьных автобусах, грузовиках доставки и других транспортных средствах, оснащенных двигателями Cummins, Detroit Diesel, Volvo или переоборудованными для работы на природном газе. Спецификации: API CK-4/SN; CUMMINS CES 20092; CUMMINS CES 20085; DETROIT DIESEL DDC 93K216; DETROIT DIESEL DFS 93K222; VOLVO VDS 4.5; Рекомендуется для двигателей Yutong, Foton, Sitrak, Shacman, FAW, Howo, JAC, Weichai Power, Yuchai, Yunnei Power.','18 л',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30005','TURBOIL SAE 40 API CF 205 л','Gulf Western Oil','motor_oil',142800,95200,'Моторные масла','SAE 40',205.0,'л',1,'Turboil 40 – это высококачественное низкозольное сезонное дизельное моторное масло, созданное специально для использования в двухтактных дизельных двигателях Detroit Diesel.Turboil 40 рекомендуется для двухтактных двигателей Detroit, у которых температура охлаждающей жидкости на выходе не превышает 94°C. Спецификации: SAE 40; API CF-4, CF-2, SG; MIL-L-2104 D & E; ALLISON C4; CATERPILLAR T0-2;  DETROIT DIESEL 7SE2709505','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30805','TURBOIL SAE 40 API CF 18 л','Gulf Western Oil','motor_oil',15300,10200,'Моторные масла',NULL,18.0,'л',1,'Turboil 40 – это высококачественное низкозольное сезонное дизельное моторное масло, созданное специально для использования в двухтактных дизельных двигателях Detroit Diesel.Turboil 40 рекомендуется для двухтактных двигателей Detroit, у которых температура охлаждающей жидкости на выходе не превышает 94°C. Спецификации: SAE 40; API CF-4, CF-2, SG; MIL-L-2104 D & E; ALLISON C4; CATERPILLAR T0-2;  DETROIT DIESEL 7SE2709505','18 л',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('305204','Syn-X LV SAE 0W-20 FULL SYN 5 л. Х 4 шт','Gulf Western Oil','motor_oil',12000,8000,'Моторные масла','SAE 0W20',5.0,'л',4,'Syn-X LV 0W-20 – это полностью синтетическое моторное масло с ультравысокими эксплуатационными характеристиками,которое подходит для широкого ряда современных автомобилей с бензиновыми и дизельными двигателями, обеспечивая максимальную производительность и защиту двигателя. Syn-X LV 0W-20 создано с учетом требований большинства ведущих европейских и американских спецификаций, где требуется низковязкое и экономичное моторное масло, в том числе для двигателей, оснащенных современными системами доочистки выхлопных газов, такими как сажевые фильтры дизельных и бензиновых двигателей. Syn-X LV 0W-20 можно использовать в случаях, когда требуется применение топливосберегающих масел, обеспечивая при этом превосходную защиту двигателя и сажевых фильтров. Syn-X LV 0W-20 рекомендуется для использования во многих гибридных двигателях благодаря улучшенной защите двигателя в режиме газ-тормоз и ресурсосберегающим свойствам масла. Спецификации: ACEA C5; API SP; ILSAC GF-6A; BMW LL17FE+ (ОБРАТНО СОВМЕСТИМО С BMW LL14FE+); MB 229.71; VOLVO VCC RBS0-2AE; FORD WSS-M2C-960-A1; OPEL OV 0401547; FIAT 9.55535-GSX; CHRYSLER MS-12145; JLR STJLR 03-5006-16; ПОДХОДИТ ТАМ, ГДЕ РЕКОМЕНДУЕТСЯ VW 508/509','5 л. Х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
