INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('60507','EURO FORCE 5W-30 LOW SAPS ACEA C4      FULL SYN 5 л. Х 4 шт','Gulf Western Oil','motor_oil',8295,5530,'Моторные масла','SAE 5W30',5.0,'л',4,'Euro Force 5W-30 – это высокопроизводительное синтетическое моторное масло для легковых автомобилей с ультранизким содержанием серы, фосфора и сульфатных зол (ultra-low SAPS), предназначенное для дизельных и некоторых бензиновых автомобильных двигателей, для которых специально разработаны спецификации ACEA C4, Ford M2C934-B, Renault RN 0720. Область применения включает отдельные модели Nissan (Navara/Pathfinder), Land Rover, Suzuki, Renault и Jaguar, которым требуется масло стандарта ACEA C4. Также может использоваться там, где требуется ACEA C1. Euro Force отличается высококачественным составом, который максимально продлевает срок службы дизельных сажевых фильтров (DPF), повышает экономию топлива и помогает увеличить интервалы между заменами масла. Примечание: Euro Force следует использовать только в тех случаях, когда оно специально рекомендовано компанией Gulf Western Oil, или там, где требуется продукт спецификации ACEA C4. Моторное масло Euro Force – это узкоспециализированная формула, которая может не подойти для многих современных легковых автомобилей, не требующих применения масла ACEA C4. Не подходит для использования в случаях, когда рекомендуется масло стандарта ACEA C2 или C3.. Спецификации: SAE 5W-30; ACEA С4; FORD M2С934-B; RENAULT RN 0720','5 л. Х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('304368','EURO ENERGY 0W-30 VW504/507 4 л. × 4 шт','Gulf Western Oil','motor_oil',7950,5300,'Моторные масла','SAE 0W30',4.0,'л',4,'EURO ENERGY 0W-30 – это высокоэффективное низкозольное синтетическое моторное масло, подходящее для легковых автомобилей последних моделей, в том числе оснащенных дизельными сажевыми фильтрами. Euro Energy 0W-30 соответствует высококлассной спецификации двигателей VW для масел с увеличенным сроком использования VW 504 00/VW 507 00, которые совместимы с дизельными сажевыми фильтрами. Благодаря технологии с низким содержанием сульфатных зол, фосфора и серы (low-SAPS) моторное масло Euro Energy подходит для автомобилей с сажевыми фильтрами. Euro Energy идеально для европейских автомобилей. Также соответствует спецификациям BMW long-life LL-04, Mercedes Benz 229.51. Спецификации: SAE 0W-30; ACEA С3; BMWLL-04; PORSCHE C30; VW 504 00 / 507 00, TL 52545','4 л. х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301368','EURO ENERGY 0W-30 VW504/507 1 л. × 12 шт','Gulf Western Oil','motor_oil',2025,1350,'Моторные масла',NULL,1.0,'л',12,'EURO ENERGY 0W-30 – это высокоэффективное низкозольное синтетическое моторное масло, подходящее для легковых автомобилей последних моделей, в том числе оснащенных дизельными сажевыми фильтрами. Euro Energy 0W-30 соответствует высококлассной спецификации двигателей VW для масел с увеличенным сроком использования VW 504 00/VW 507 00, которые совместимы с дизельными сажевыми фильтрами. Благодаря технологии с низким содержанием сульфатных зол, фосфора и серы (low-SAPS) моторное масло Euro Energy подходит для автомобилей с сажевыми фильтрами. Euro Energy идеально для европейских автомобилей. Также соответствует спецификациям BMW long-life LL-04, Mercedes Benz 229.51. Спецификации: SAE 0W-30; ACEA С3; BMWLL-04; PORSCHE C30; VW 504 00 / 507 00, TL 52545','1 л. х 12 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('304171','ENERGY PLUS 5W-30 VW504/507 4 л. × 4 шт','Gulf Western Oil','motor_oil',6000,4000,'Моторные масла','SAE 5W30',4.0,'л',4,'Energy Plus 5W-30 – это синтетическое моторное масло с высокими рабочими характеристиками, подходящее для моделей легковых автомобилей последних лет, в том числе оснащенных сажевыми дизельными фильтрами. Масло Energy Plus 5W-30 соответствует высокотребовательной спецификации Volkswagen для масел с увеличенным сроком до замены и совмеcтимых с сажевыми фильтрами VW 504 00/VW 507 00. Формула Energy Plus 5W-30 с низким содержанием серы, фосфора и сульфатных зол (low-SAPS) подходит для автомобилей с сажевым дизельным фильтром. Это идеальный продукт для таких европейских автомобилей, как VW, BMW и других, масла для которых должны отвечать требованиям спецификации ACEA С3. Кроме того, продукт соответствует спецификациям BMW long-life LL-04 и Mercedes Benz 229.51.                                                 Спецификации: SAE 5W-30; ACEA С3; API SP; BMW LONGLIFE-04; MB 229.51; VW 504.00 / 507.00','4 л. х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301171','ENERGY PLUS 5W-30 VW504/507 1 л. × 8 шт','Gulf Western Oil','motor_oil',2025,1350,'Моторные масла',NULL,1.0,'л',8,'Energy Plus 5W-30 – это синтетическое моторное масло с высокими рабочими характеристиками, подходящее для моделей легковых автомобилей последних лет, в том числе оснащенных сажевыми дизельными фильтрами. Масло Energy Plus 5W-30 соответствует высокотребовательной спецификации Volkswagen для масел с увеличенным сроком до замены и совмеcтимых с сажевыми фильтрами VW 504 00/VW 507 00. Формула Energy Plus 5W-30 с низким содержанием серы, фосфора и сульфатных зол (low-SAPS) подходит для автомобилей с сажевым дизельным фильтром. Это идеальный продукт для таких европейских автомобилей, как VW, BMW и других, масла для которых должны отвечать требованиям спецификации ACEA С3. Кроме того, продукт соответствует спецификациям BMW long-life LL-04 и Mercedes Benz 229.51.                                                 Спецификации: SAE 5W-30; ACEA С3; API SP; BMW LONGLIFE-04; MB 229.51; VW 504.00 / 507.00','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
