INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30534','GULF 1 FULL SYN 10W60 5 л. × 4 шт','Gulf Western Oil','motor_oil',8655,5770,'Моторные масла','SAE 10W60',5.0,'л',4,'GULF 1– это синтетическое моторное масло премиум-класса для бензиновых и легких дизельных двигателей, предназначенное для максимальной защиты двигателя. Моторное масло GULF 1 производится на основе высокоэффективного синтетического базового масла и соответствует последним спецификациям всех современных производителей двигателей и техники. Спецификации: SAE 10W-60; ACEA A3/B4; API SP/CF','5 л. х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300129Pr','SYN-X 6000 FULL SYN SN/GF-5 GM DEXOS 205 л','Gulf Western Oil','motor_oil',240000,160000,'Моторные масла','SAE  5W-30',205.0,'л',1,'Syn-X 6000 – это полностью синтетическое моторное масло для легковых автомобилей, созданное в соответствии с современными требованиями к характеристикам смазочных материалов. Подходит для бензиновых и дизельных двигателей, в том числе оснащенных сажевыми фильтрами. SYN-X 6000 обеспечивает полную защиту двигателя и высокий уровень экономии топлива, демонстрируя рабочие показатели выше, чем у обычных моторных масел. Благодаря синтетическим базовым маслам продукты SYN-X 6000 обладают исключительной термической устойчивостью, более стабильным уровнем вязкости, а также отличной низкотемпературной текучестью, что делает данные продукты всесезонными. Сбалансированный пакет современных присадок в составе масел SYN-X 6000 обеспечивает высокий уровень защиты от износа и окисления, чистоту двигателя даже в самых сложных условиях эксплуатации. Современные технологии, использованные в SYN-X 6000, защищают бензиновые двигатели с турбонаддувом и прямым впрыском топлива от раннего зажигания на низких оборотах (LSPI). Спецификации: API SP/CF; ACEA C2/C3; MB 229.31/229.51/226.5; VW 502.00/505.00/505.01; OPEL GM-LL-B-025; BMW Longlife-04; Porsche A40; Renault RN0710/0700; PSA B71 - 2296;  Dexos 2; CHRYSLER MS-13340. Использование в автомобилях с сажевыми фильтрами (DPF, GPF)','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
