INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301272','POWER ARCTIC 4T 0W40 1 л. × 8 шт','Gulf Western Oil','moto4t',3075,2050,'Масла для 4-тактной техники','SAE 0W40',1.0,'л',8,'POWER ARCTIC 4T 0W-40 – это современное синтетическое моторное масло на основе ПАО и эфиров, разработанное для особых условий эксплуатации снегоходов, вездеходов, мотовездеходов и другой четырехтактной техники, работающей в суровых условиях арктического климата. Данное масло совместимо с этилированными и неэтилированными бензинами, биотопливом и другими специализированными видами топлива, используемыми в четырехтактных двигателях, работающих в суровых арктических условиях. Обладая прекрасной текучестью, POWER ARCTIC 4T   0W-40 обеспечивает защиту техники там, где обычные масла не справляются в условиях низких температур. Продукт рекомендуется для снегоходов, квадроциклов, других видов мотовездеходов, требующих применения масла 0W-40, в том числе для техники Polaris, Honda, Yamaha, Suzuki, Kawasaki, BRP, Arctic Cat и других современных высокопроизводительных четырехтактных двигателей.API SN; JASO MA2','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
