INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('304110','FOUR STROKE FC-W INBOARD/OUTBOARD 25W40 SYNTHETIC 4 л. × 4 шт','Gulf Western Oil','moto4t',5775,3850,'Масла для 4-тактной техники','SAE 25W40',4.0,'л',4,'OUTBOARD FC-W 25W-40 – полусинтетическое моторное масло для малых двигателей. Это масло специально разработано для современных 4-тактных подвесных двигателей и отвечает требованиям стандарта NMMA FC-W. API SG; NMMA FC-W; API SG; JASO MA','4 л. х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301389','SNOW ARTIC POWER TWO STROKE FULL SYNTHETIC E-TEC 1 л. × 12 шт','Gulf Western Oil','moto2t',1650,1100,'Масла для 2-тактных двигателей',NULL,1.0,'л',12,'SNOW ARCTIC POWER 2 STROKE – это современное, высокопроизводительное, полностью синтетическое моторное масло, созданное специально для особых условий эксплуатации всех двухтактных двигателей снегоходов, вездеходов, квадроциклов и другой двухтактной силовой техники, работающей в суровых условиях, особенно в экстремально холодном климате. Совместимо с этилированным и неэтилированным бензином, биотопливом и другими специализированными видами топлива, используемыми в двухтактных двигателях, работающих в условиях холодной зимы.   Для двигателей с технологией E-TEC и C-TEC2API TC; ISO-L-EGD; JASO FD, FC; TISI','1 л. х 12 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301268SD','AIR COOLED SYNTHETIC TWO STROKE 1 л. × 12 шт','Gulf Western Oil','moto2t',1532,1021,'Масла для 2-тактных двигателей',NULL,1.0,'л',12,'TWO STROKE - AIR COOLED OIL - это синтетическое низкозольное масло премиум-класса, предназначенное для двухтактных двигателей с предварительным смешиванием топлива и масла, а также с впрыском масла. В состав TWO STROKE AIR COOLED Oil входят синтетические базовые масла и высокоэффективный низкозольный пакет присадок, который обеспечивает превосходную противозадирную и противоизносную защиту, внутреннюю чистоту и длительный срок службы двигателя. Тщательно сбалансированный уровень зольности обеспечивает контроль образования нагара на свечах зажигания и предотвращает преждевременное зажигание. Соответствует требованиям JASO FC, ISO-L-EGC и API TC.','1 л. х 12 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
