INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('62050','ULTRA CLEAR GEAR OIL LUBE LS 75W-85 FULL SYN 20 л','Gulf Western Oil','transmission',30000,20000,'Трансмиссионные масла','SAE 75W-85',20.0,'л',1,'Ultra Clear Gear Oil® 75W-85 – синтетическое трансмиссионное масло с высокими эксплуатационными характеристиками для современных механических коробок передач. Ultra Clear Gear Oil® 75W-85 рекомендуется использовать, если производителем указано масло SAE 75W или 80W. Сбалансированные вязкость и фрикционные свойства обеспечивают стабильно плавное и быстрое переключение передач. Спецификации: SAE 75W-85; API GL-5; Borg Warner 5M-42; Ford ESP-M2C83-C;       Mitsubishi ES-X-64021','20 л',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
