INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301214','MARINE GEAR OIL 75W-90 FULL SYN 1 л. × 8 шт','Gulf Western Oil','transmission',1950,1300,'Трансмиссионные масла','SAE 75W-90',1.0,'л',8,'MARINE GEAR OIL 75W-90 (GL-5) – это полностью синтетическое трансмиссионное масло премиум-класса для защиты редукторов подвесных моторов и поворотно-откидных колонок водной техники. Это устойчивое к сдвигу, полностью синтетическое всесезонное трансмиссионное масло обеспечивает исключительно плавное переключение даже в холодном состоянии, обеспечивая защиту на уровне трансмиссионного масла SAE 90 при полной рабочей температуре. Синтетические базовые масла и усовершенствованный пакет присадок обеспечивают длительный срок службы и полную защиту редукторов в суровых морских условиях. Морское трансмиссионное масло MARINE GEAR OIL 75W-90 рекомендуется использовать в агрегатах таких производителей, как Chrysler, Honda, Johnson/Evinrude, Mercury, Suzuki, Tohatsu, Volvo-Penta, Yamaha и всех ведущих производителей морского оборудования, когда ими указаны трансмиссионные масла SAE 90, 85W-90, 80W-90 или   75W-90; API GL-5.','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
