INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30051B','Gear Lube 80W90 1000л','Gulf Western Oil','transmission',0,NULL,'Трансмиссионные масла','SAE 80W-90',1000.0,'л',1,'Gulf Western Gear Lube – противозадирное трансмиссионное масло для работы в тяжелых условиях, разработанное для использования в линейных или гипоидных, фрикционных и винтовых передачах в трансмиссиях, осях и бортовых передачах, работающих в условиях высокоскоростных операций с малым крутящим моментом и в условиях низкоскоростных операций с высоким крутящим моментом. Это превосходное многоцелевое противозадирное масло для дифференциалов и механических коробок передач в легковых автомобилях, грузовиках, автофургонах, автобусах, а также в тяжелой технике. Спецификации: API GL-4 and GL-5; Mack GO-H; US Military MIL-L-2105D/2106; Eaton; Rockwell','1000л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
