INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30044','AGRITRANS UTTF 205 л','Gulf Western Oil','transmission_offroad',153000,102000,'Трансмиссионные для внедорожной техники',NULL,205.0,'л',1,'Agritrans UTTF – это многоцелевое масло для тракторов, которым требуется одно смазочное масло для трансмиссии, гидравлики, дифференциалов, бортовой передачи, мокрого сцепления и тормозов. Масло Agritrans UTTF было разработано специально с учетом требований широкого ряда спецификаций большинства современных производителей тракторов и гидравлических насосов. В состав Agritrans UTTF входит противоскрипная присадка для эффективной работы мокрых тормозов. Технология присадок Gulf Western выдержала испытания при использовании в более чем 250 тракторах, что в сумме составляет более 200 000 часов полевых испытаний. Спецификации:API GL-4; SAE 10W-30 (Table J300); SAE 80W (Table J306); JOHN DEERE J20С и более ранние; FORD/NEW HOLLAND; CNH; INTERNATIONAL HARVESTER; STEIGER; VERSATILE; DEUTZ-ALLIS; FIAT; KUBOTA; MASSEY FERGUSON; ALLIS-CHALMERS POWER FLUID821; ALLISON C4; Полный список спецификаций находится сайте www.gulfwestern.com.au','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
