INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300263','SYN-TORQUE OIL 5W30 205 л','Gulf Western Oil','transmission_offroad',269700,179800,'Трансмиссионные для внедорожной техники',NULL,205.0,'л',1,'Syn-Torque Oil 5W-30 – всесезонная синтетическая жидкость, изготовленная на основе синтетических полиальфаолефиновых базовых компонентов (ПАО) и современного пакета присадок. Предназначена для трансмиссий, бортовых передачах, гидравлических систем Caterpillar, Komatsu и другой внедорожной строительной и карьерной техники. Применение данного продукта улучшает рабочие характеристики и продлевает срок службы систем. Жидкость Gulf Western Syn-Torque Oil 5W-30 рекомендована для всесезонного использования, особенно для техники, работающей при очень низкой температуре, а также для круглогодичного обслуживания в любых климатических условиях. Спецификации: SAE 5W-30; Caterpillar TO-4','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
