INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300276','SYN-TS ULV 205 л.','Gulf Western Oil','atf',249300,166200,'Жидкости для АКПП',NULL,205.0,'л',1,'SYN-TS® ULV – это современная синтетическая трансмиссионная жидкость для автоматических трансмиссий, которая обладает ультранизкой вязкостью и исключительно высокими рабочими характеристиками и отвечает требованиям новейших трансмиссий с большим количеством передач таких производителей, как Ford, GM, Lexus, Mercedes Benz, Volkswagen. Благодаря сверхвысокой устойчивости к сдвигу и увеличенному сроку службы трансмиссионная жидкость SYN-TS® ULV демонстрирует превосходные характеристики в широком диапазоне применений, включая тяжелую буксировку.Спецификации: AISIN WARNER AW-2; AUDI G 053 001, AUDI G 060 540; BMW/MINI 83 22 2 413 477 (ATF7); FORD WSS-949-A, MERCON ULV; GM ULV; MAZDA ATF-7; MERCEDES BENZ MB 236.15, 236.16, 236.17; NISSAN MATIC P; SEAT G 053 001, G 060 540; SKODA G 053 001, G 060 540;     VW G 060 540, VW G 053 001; VOLVO 31 492 172, VOLVO 31 492 173','205 л.',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
