INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301356','SYN-TS MV Red 1 л. × 12 шт','Gulf Western Oil','atf',1650,1100,'Жидкости для АКПП','Синтетическая жидкость для автоматических коробок передач',1.0,'л',12,'Syn-TS® MV Red специально разработана для азиатских OEM-производителей, но также соответствует требованиям американских и европейских производителей техники. Жидкость Syn-TS MV Red изготавливается на основе синтетических базовых масел с добавлением современных высокотехнологичных присадок, созданных для достижения идеального баланса фрикционных характеристик, способствующих мягкому переключению передач, улучшению передачи активной мощности, препятствующих жесткой работе элементов трансмиссии. Соответствует спецификациям производителей: JASO M315 Тип 1A; Toyota Тип T, T-II,T-III и T-IV; Toyota WS; Toyota Тип D-2; Nissan Matic Fluid C; Nissan Matic Fluid D; Nissan Matic Fluid J; Mitsubishi SP-II и SP-III; Subaru ATF; Isuzu BESCO ATF-II и ATF-III; Suzuki ATF Oil и ATF Oil Special; Mazda ATF D-III, ATF M-3; Daihatsu Alumix ATF Multi; Hyundai SP III; Honda (кроме CVT); Kia SP III; GM Daewoo/Shanghai GM; GM DEXRON II; GM DEXRON III; Ford MERCON; Allison C-4; Aisin-Warner Transmissions; 4 и 5 скоростные европейские трансмиссии (BMW, MB 236.1 и VW); ZF Commercial ATs (TEML 14A); Voith Commercial ATs (55.6335); MANCommercial ATs, (MAN 339 Type Z-1 и V-1)','1 л. х 12 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30041','ATF DX-III 205 л','Gulf Western Oil','atf',144840,96560,'Жидкости для АКПП','Многофункциональная жидкость для автоматических трансмиссий',205.0,'л',1,'ATF Dex III – трансмиссионная жидкость, предназначенная для использования в автоматических трансмиссиях, где требуется жидкость Dexron® III, Dexron® II или Mercon®. Продукт также широко применяется в качестве жидкости для гидроусилителя руля. Подходит для использования с компонентами трансмиссий новейших поколений, обладает высокой стабильностью и надежностью при повышенных рабочих температурах. Спецификации: GM DEXRON III-H, Ford MERCON, ESP 138CJ, M2C 166 -H, Allison C-4, Caterpillar TO-4, Vickers 35VQ25, Denison HF -1, HF-2','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
