INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300172','SUPERDRAULIC 205 л','Gulf Western Oil','hydraulic',122250,81500,'Гидравлические масла','ISO VG 32',205.0,'л',1,'Superdraulic® – серия противоизносных гидравлических масел с высокими рабочими характеристиками. Формула Superdraulic® создана с использованием высокоочищенных базовых масел и усилена цинковым противоизносным и противоокислительным ингибиторами и противовспенивающими присадками. Как результат, продукты Superdraulic® обладают высокой температурной устойчивостью и выдерживают усиленные нагрузки при высоких температурах. Спецификации:  ISO Viscosity Grades 22, 32, 46, 68, 100, 150, 220; Cincinnati Milacron P68, P69, P70; Denison HF-0, HF-1, HF-2; DIN 51 524 Part 2 (масла HLP); US Steel 136, 127; Vickers 1-286-S, M2952-S. Отвечает требованиям: Hagglund; Rexroth; Danfoss; Linde; Bosch; Racine; Commercial Hydraulics; Sunstrand; Cincinnati Milacron; Vickers; Oilgear; Denison','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
