INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300262','SUPERDRAULIC ARCTIC 32 205 л','Gulf Western Oil','hydraulic',210000,140000,'Гидравлические масла','ISO VG 32',205.0,'л',1,'SUPERDRAULIC ARCTIC 32 – высококачественное гидравлическое масло с превосходными низкотемпературными свойствами, благодаря которым оно сохраняет текучесть при температурах, при которых обычные гидравлические жидкости не обеспечивают надежную и безопасную работу оборудования. Продукт создан на основе тщательно подобранных базовых компонентов и специального пакета присадок, обладает исключительно высоким индексом вязкости (VI>300). Cпецификаций: Dietz Automation Gmbh (испытание для сервоклапанов и пропорциональных клапанов); DIN 51524 Part 3, Противоизносные гидравлические масла, Type HVLP; GB 111181-1-94 (HV Fluids); ISO 11158 (HV Fluids); Komatsu (гидравлические системы, эксплуатируемые в условиях холодного климата); Komatsu Mining (эксплуатация в условиях холодного климата, от -50°С до 35°С)','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('308262','SUPERDRAULIC ARCTIC 32 18 л','Gulf Western Oil','hydraulic',21450,14300,'Гидравлические масла',NULL,18.0,'л',1,'SUPERDRAULIC ARCTIC 32 – высококачественное гидравлическое масло с превосходными низкотемпературными свойствами, благодаря которым оно сохраняет текучесть при температурах, при которых обычные гидравлические жидкости не обеспечивают надежную и безопасную работу оборудования. Продукт создан на основе тщательно подобранных базовых компонентов и специального пакета присадок, обладает исключительно высоким индексом вязкости (VI>300). Cпецификаций: Dietz Automation Gmbh (испытание для сервоклапанов и пропорциональных клапанов); DIN 51524 Part 3, Противоизносные гидравлические масла, Type HVLP; GB 111181-1-94 (HV Fluids); ISO 11158 (HV Fluids); Komatsu (гидравлические системы, эксплуатируемые в условиях холодного климата); Komatsu Mining (эксплуатация в условиях холодного климата, от -50°С до 35°С)','18 л',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30047','TORQUE OIL 10W 205 л','Gulf Western Oil','hydraulic',137550,91700,'Гидравлические масла','10W',205.0,'л',1,'Torque Oil – трансмиссионная жидкость с допуском Caterpillar TO-4. Фрикционные характеристики Torque Oil превосходят требования стандарта TO-2. Продукт разработан, чтобы увеличить срок службы и улучшить работу всех гидравлических систем техники Caterpillar, а также Komatsu. Кроме того, продукты Torque Oil 10W отвечают требованиям спецификации Allison C4. Torque 10W подходит для использования в гидравлических системах во всех случаях, где нужна гидравлическая жидкость 10W или 15W, также подходит для гидростатических трансмиссий.Cпецификации: SAE 10W; API GL-3 (Torque Oil 10W); Caterpillar T0-4; Alison C4, Komatsu (Torque Oil 10W)','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
