INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300384','ULTRA CLEAR COMPRESSOR FULL SYNTHETIC 205 л','Gulf Western Oil','compressor',332250,221500,'Компрессорные масла','VG 32',205.0,'л',1,'Ultra Clear Compressor – это высококачественное многоцелевое синтетическое беззольное компрессорное масло с высоким индексом вязкости, предназначенное для использования в роторных лопастных и винтовых воздушных компрессорах. Созданное на основе высокоустойчивых полиальфаолефиновых базовых масел, Ultra Clear Compressor отличается исключительными защитными свойствами при применении в широком диапазоне температур.Спецификации: DIN 51506 VDL (VCL, VBL) ISO 6743/3 DAG, DAH Ultra Clear Compressor отвечает требованиям большинства современных производителей воздушных компрессоров, включая следующих (но не только): • Atlas Copco –модели серий GA и GAU • Jaeger Machine Company роторные винтовые и лопастные • Atlas Copco мобильные роторные винтовые XA XAH • LeRoi Division • Sullair & Ingersoll Rand High Pressure Compressors • Dresser Industries мобильные и стационарные','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
