INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('301940','COMPRESSOR OIL ISO VG 100 1 л. × 8 шт','Gulf Western Oil','compressor',1650,1100,'Компрессорные масла',NULL,1.0,'л',8,'Compressor Oil SAE 30 - ISO 100 – это премиальное компрессорное масло, произведенное на основе высокоочищенных базовых компонентов, отличающихся превосходной окислительной стабильностью, и тщательно подобранного пакета присадок, что позволяет получить продукт с низкой способностью к сажеобразованию даже при высоких температурах. Подходит для смазки как цилиндров, так и картеров компрессоров, работающих при высоких температурах нагнетания до 220 °C. COMPRESSOR OIL SAE 30 – ISO 100 — это универсальное компрессорное масло без моющих присадок, которое отвечает потребностям поршневых воздушных компрессоров, ротационных компрессоров с капельной подачей, а также в некоторых случаях применения в качестве гидравлического масла или масла с ингибиторами ржавчины и окисления. Спецификации:                        ISO 100 / SAE 30; DIN 51506 VDL; DIN 51524 Part 2; AFNOR NFE 48-603 (HM); SPERRY VICKERS I-286-S','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300256','Ultra Clean Turbine 205 л','Gulf Western Oil','turbine',173850,115900,'Турбинные масла','VG 32',205.0,'л',1,'Ultra Clean Turbine Oil – это линейка турбинных масел с увеличенным сроком службы, содержащих ингибиторы коррозии и окисления. Продукты созданы на основе высокоочищенных минеральных базовых масел и запатентованных премиальных пакетов присадок, обеспечивающих длительный срок службы турбин в тяжелых условиях эксплуатации. Масла Ultra Clean Turbine Oil обладают высокой стойкостью к окислению и обеспечивают превосходную защиту от коррозии металлических поверхностей важнейших компонентов турбин. Данные масла отличаются высокими эксплуатационными характеристиками, демонстрируют превосходные деэмульгирующие свойства, отличную фильтруемость, очень быстрое выделение воздуха. Спецификации:ALSTOM HGD 90117T; ANSI/AGMA 9005-D94 (R & O); BS 489; CINCINNATI MACHINE P-39; DIN 51 515 PART 1 (TD); DIN 51 515 PART 2 (TG); DIN 51 517 PART 1/2 (C/CL); GEK 101941 A; GEK 107395 AGEK 28568 A; GEK 32568 F; GM LS-01/02/03-1-97; GM LJ-03/04/06/10-2-97; GM LJ-03/04/06/10-1-97; MIL-PRF-17331J; MORGAN WORCHESTER ADVANCED LUBRICANT; MORGAN WORCHESTER STANDARD LUBRICANT; SEB 181 225; SIEMENS TLV 9013; SOLAR ES 9-224 (CLASS I/CLASS II); VOITH SULZER VN 108','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
