INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('40056','Long Life Organic Concentrated Coolant 205 л','Gulf Western Oil','coolant',210300,140200,'Антифризы',NULL,205.0,'л',1,'LONG LIFE ORGANIC COOLANT – это  органическая охлаждающая жидкость премиум класса с длительным сроком службы для защиты от закипания/замерзания, с составом на основе карбоксилатной технологии, не содержащий силикатов, боратов, фосфатов, нитритов, нитратов и аминов. Подходит как для автомобильных, так и для тяжелых дизельных двигателей. Обеспечивает максимальную защиту от коррозии типа «горячих точек», характерной для алюминиевых головок цилиндров. Срок службы – до 5 лет / 500 000 км* в автомобилях и до 6 лет / 600 000 км / 6000 часов* в тяжелых дизелях. Cпецификаций: AS 2108.1: 2004 TYPE A; AFNOR NFR 15-601; ASTM D3306, D4656, D4985; BS 6580; GM 6277 M; GM 1825 M &GM 1899 M; FORD ESE FM 97B18-C; FORD ESE M 978B4H-A; FORD ESE M 99B166-C; TOYOTA K2601G-1G; ISUZU; IVECO; HYUNDAI; VOLKSWAGEN; MAZDA MES MN 1210; JAPANESE JIS K 2234; SAE J 1034 AND JASO M 324; VOLVO (SPEC. NO 1286083); BMW N 600 69.0; MERCEDES BENZ MBApproval 325.3; NISSAN NES 5059 LLC; CUMMINS 3666132; SAAB FSD 8074; CATERPILLAR 1 EO 535; DAF 742002/BTPS; 606A/DCEA 615; KIA; SUBARU; MITSUBISHI; BRITISH LEYLAND; KOMATSU KES 07.892; JENBACHER; LIEBHERR MD 1-36-130; MAN 324 TYPE SNF; WAUKESHA 4-1974D; SAAB SCANIA® 6901','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
