INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('40555','All FLEET HDD COOLANT PRE-MIXED 5 л. × 4 шт','Gulf Western Oil','coolant',4065,2710,'Антифризы',NULL,5.0,'л',4,'All Fleet HDD Coolant – это охлаждающая жидкость превосходного качества, разработанная с учетом особенностей гибридных двигателей. Имеет люминесцентный зеленый цвет. Преимущество этой охлаждающей жидкости в том, что она более надежна, чем охлаждающая жидкость двигателей, изготовленных по традиционной технологии и на основе органических кислот (OAT). Спецификации: ASTM D3306, D4985, D6210; Caterpillar; Cummins 14603; Detroit Diesel 7SE 298; Daimler Chrysler MS 7170, MS 9769; Ford ESEM97B44A, ESEM97B18C, Ford WSSM97B51A1; Freightliner 482288D; GM 1825M, 1899M, GM Heavy Truck; Hyundai; JIS K2234; Kenworth RO2617097; Landrover; MACK Trucks; MAN 324; Mercedes-Benz DBL 325; MTU MTL 5048White Star; US Federal AA870A; New Holland WSNM97B18-D; PACCAR; Peterbilt 8502.002; Perkins; Saab-Scania 6901; SAE J1034, J1941; TMC RP 329; Volvo Heavy Truck','5 л. х 4 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('40056R','All FLEET Antifreeze Coolant 205 л','Gulf Western Oil','coolant',153000,102000,'Антифризы','RED концентрат',205.0,'л',1,'All Fleet HDD Coolant – это готовая к использованию высококачественная гибридная охлаждающая жидкость для двигателя, окрашенная в красный или зеленый цвет. Благодаря гибридной технологии All Fleet HDD Coolant сочетает преимущества традиционных охлаждающих жидкостей и тех, в которых используются органические кислоты (ОАТ). Этот низкосиликатный, не содержащий фосфатов и аминов продукт, совместимый с алюминием, рекомендуется для дизельных автомобилей, эксплуатируемых в легких и тяжелых условиях: шоссейных и внедорожных грузовиков, сельскохозяйственной и морской техники. Обеспечивает отличную защиту алюминиевых деталей при высоких рабочих температурах.
