INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30111','Power Steering Fluid 1 л. × 8 шт','Gulf Western Oil','ps_fluid',1950,1300,'Жидкость ГУР',NULL,1.0,'л',8,'Универсальная жидкость для гидроусилителя руля, которая прекрасно работает при низких температурах, когда большинство жидкостей уже теряют свою эффективность. Формула данной жидкости снижает износ деталей системы гидроусилителя, поддерживает чистоту системы, снижает шум, защищает прокладки и шланги, снижает нагрев и вспенивание жидкости, позволяет увеличить период до замены. Спецификации: DX-3; CATERPILLAR TO-2; CHRYSLER MS-5931; GM 9985010; ALLISON C4; FORD MERCON®; FORD ESW-M2C128-C; MERCEDES BENZ; MAZDA; VOLVO; VOLKSWAGEN TL-VW-570-26','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('40101','Brake Fluid Dot 4 0,5 л. × 16 шт','Gulf Western Oil','brake',1185,790,'Тормозная жидкость','Dot 4',0.5,'л',16,'Tормозная жидкость с высокими характеристиками для использования как в легковых, так и грузовых транспортных средствах, в том числе оснащенных системами ABS. Высокая термостойкость и низкое поглощение влаги обеспечивают превосходные показатели температуры кипения и температуры образования паровой пробки в течение всего срока службы жидкости Спецификации:  Австралийский стандарт - AS/NZS 2960.1-1995 DOT4/Grade 3; SAE J 1703; ISO 4925; FMV SS 571-116','0,5 л. х 16 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
