INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('400415','FOODTECH MACHINERY GREASE 0,38 кг. × 12 шт','Gulf Western Oil','grease',1575,1050,'Смазки','NLGI 2',0.38,'кг',12,'Foodtech Machinery Grease – это смазка для пищевого оборудования класса H1 с составом на основе алюминиевого комплексного загустителя, фармацевтического белого масла и полимера. Продукт содержит антиоксиданты, противозадирные и противоизносные присадки (EP/AW) и белые твердые смазочные материалы (синтетическое фторированное полиэфирное масло, PTFE). Спецификации: ISO 12924: L-XB(F)CHB2; DIN 51502: KP2K-15','0,38 кг. х 12 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('300369','SUPER-SYN LX GREASE 180 кг','Gulf Western Oil','grease',644205,429470,'Смазки',NULL,180.0,'кг',1,'SUPER-SYN LX Grease – это смазка на основе синтетического масла, загущенная литиевым комплексом. Смазка содержит антиоксиданты, ингибиторы коррозии и комплекс противозадирных и противоизносных присадок (EP/AW), произведенных по висмутовой технологии Специально разработанный пакет висмутовых присадок обеспечивает повышенную способность переносить высокие нагрузки, а также противостоять вибрационным и ударным нагрузкам. Смазка SUPER-SYN LX Grease – это современный высокоэффективный синтетический продукт, подходящий для индустриального и автомобильного применения. Универсальные свойства продукта и широкий температурный диапазон делают ее основным выбором для различных типов подшипников, в том числе в условиях высоких нагрузок. Консистенция смазки подходит для использования в промышленных централизованных смазочных системах.Спецификации: ISO 12924: L-XD (F) DIB1.5; DIN 51502: KPHC1.5N-40','180 кг',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
