INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('304369','SUPER-SYN LX GREASE 0,42 мл. × 12 шт','Gulf Western Oil','grease',2190,1460,'Смазки',NULL,NULL,NULL,NULL,'SUPER-SYN LX Grease – это смазка на основе синтетического масла, загущенная литиевым комплексом. Смазка содержит антиоксиданты, ингибиторы коррозии и комплекс противозадирных и противоизносных присадок (EP/AW), произведенных по висмутовой технологии Специально разработанный пакет висмутовых присадок обеспечивает повышенную способность переносить высокие нагрузки, а также противостоять вибрационным и ударным нагрузкам. Смазка SUPER-SYN LX Grease – это современный высокоэффективный синтетический продукт, подходящий для индустриального и автомобильного применения. Универсальные свойства продукта и широкий температурный диапазон делают ее основным выбором для различных типов подшипников, в том числе в условиях высоких нагрузок. Консистенция смазки подходит для использования в промышленных централизованных смазочных системах.Спецификации: ISO 12924: L-XD (F) DIB1.5; DIN 51502: KPHC1.5N-40','0,42 мл. х 12 шт.',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('44451','SUPER BLUE GREASE NLGI 2 0,4 кг. × 12 шт','Gulf Western Oil','grease',1268,845,'Смазки','NLGI 2',0.4,'кг',12,'Super Blue Grease – это превосходная многоцелевая смазка, обладающая отличными смазывающими свойствами, для широкого ряда подшипников качения и скольжения, шестерен и муфт в автомобильной, морской, сельскохозяйственной и промышленной областях. Противозадирные и противоизносные свойства позволяют смазке Super Blue обеспечивать длительный срок службы деталей в условиях высоких и ударных нагрузок в широком диапазоне температур – от низких до очень высоких. Благодаря высокой устойчивости к сдвигу в сочетании с наличием эффективных ингибиторов ржавчины, окисления и коррозии, а также адгезионных добавок, повышающих липкость, эта смазка особенно рекомендуется для подшипников качения, герметизированных на весь срок службы. NLGI-2','0,4 кг. х 12 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
