INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('40492SD','CHASSIS GREASE CH3 0,4 кг. × 20 шт гармошка','Gulf Western Oil','grease',960,640,'Смазки','NLGI 3',0.4,'кг',20,'CHASSIS GREASE CH – это линейка высококачественных смазок общего назначения, подходящих для целого ряда применений. Эти адгезивные и водостойкие смазки обеспечивают экономичное смазывание в условиях, где скорости и температуры нанесения низкие и умеренные. Смазка отличается высокой стойкостью к вымыванию водой и надежно прилипает к движущимся деталям, таким как шаровые шарниры, ходовая часть и карданные шарниры, и подходят для ручной смазки или автоматических смазочных систем. Данная смазка подходит для широкого спектра применений в автомобилях, включая тракторы, грузовики, землеройную технику и легковые автомобили.','0,4 кг. х 20 шт. гармошка',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
