INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('320025','POLYUREA NEVER MELT GREASE 20 кг','Gulf Western Oil','grease',30000,20000,'Смазки','NLGI 2',20.0,'кг',1,'POLYUREA NEVER MELT GREASE NLGI 2 – это высокоэффективная смазка с полимочевинным загустителем. В состав данной смазки входят ингибиторы коррозии, противоокислительные, противозадирные и противоизносные присадки. Благодаря беззольному полимочевинному загустителю с его антиокислительными свойствами данная смазка может применяться в широком рабочем диапазоне, в том числе при повышенных температурах. Структура полимочевины также придает смазке высокую стойкость к механическому воздействию при вибрации, что позволяет увеличить интервалы до обслуживания. POLYUREA NEVER MELT GREASE подходит как для общей смазки, так и специализированной смазки подшипников, герметизированных на весь срок службы, включая подшипники в электродвигателях. Благодаря повышенной стойкости к окислению, хорошим диэлектрическим свойствам, превосходной термостойкости и способности выдерживать высокие нагрузки, а также исключительной устойчивости к сдвигу POLYUREA NEVER MELT GREASE является высокоэффективной смазкой с широким спектром применения.','20 кг',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('318025SS','POLYUREA GREASE 18 кг','Gulf Western Oil','grease',30000,20000,'Смазки','NLGI 2',18.0,'кг',1,'Polyurea Grease NLGI 2 – это премиальная смазка с увеличенным сроком службы на минеральной основе, загущенная полимочевиной. В состав смазки Polyurea Grease входят ингибиторы коррозии, противоокислительные, противозадирные и противоизносные присадки. Благодаря беззольному полимочевинному загустителю с его противоокислительными свойствами данная смазка подходит для применения в широком рабочем диапазоне даже при повышенных температурах. Структура полимочевины также придает смазке высокую стойкость к механическому воздействию при вибрации, что позволяет увеличить интервалы до обслуживания.','18 кг',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('138182','OPEN GEAR LUBE HD 18 кг','Gulf Western Oil','grease',47925,31950,'Смазки',NULL,18.0,'кг',1,'Open Gear Lube HD – это многоцелевое компаундированное адгезивное масло для открытых передач, предназначенное для тяжелых условий эксплуатации. Масло Open Gear Lube HD разработано специально для открытых передач и производится на основе высоковязкого масла, литиевого загустителя с дисульфидом молибдена, твердых смазочных материалов и тщательно подобранных присадок. Подходит для высоконагруженных открытых и полузакрытых передач карьерных экскаваторов, драглайнов и экскаваторной техники, эксплуатиируемой в подземных шахтах и открытых карьерах. Представляет собой сбалансированную смесь высококачественных базовых жидкостей, антиокислительных, противоизносных и противозадирных присадок, дисульфида молибдена, твердых смазочных материалов и ингибиторов коррозии. Прочная адгезионная пленка противостоит выдавливанию, что позволяет маслу прочно удерживаться на шестернях.','18 кг',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('130182','OPEN GEAR LUBE HD 180 кг','Gulf Western Oil','grease',459450,306300,'Смазки',NULL,180.0,'кг',1,'Open Gear Lube HD – это многоцелевое компаундированное адгезивное масло для открытых передач, предназначенное для тяжелых условий эксплуатации. Масло Open Gear Lube HD разработано специально для открытых передач и производится на основе высоковязкого масла, литиевого загустителя с дисульфидом молибдена, твердых смазочных материалов и тщательно подобранных присадок. Подходит для высоконагруженных открытых и полузакрытых передач карьерных экскаваторов, драглайнов и экскаваторной техники, эксплуатиируемой в подземных шахтах и открытых карьерах. Представляет собой сбалансированную смесь высококачественных базовых жидкостей, антиокислительных, противоизносных и противозадирных присадок, дисульфида молибдена, твердых смазочных материалов и ингибиторов коррозии. Прочная адгезионная пленка противостоит выдавливанию, что позволяет маслу прочно удерживаться на шестернях.','180 кг',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('41078S','CLEARONOX AdBlue 10 л.','Gulf Western Oil','adblue',5250,3500,'AdBlue',NULL,10.0,'л',1,'Gulf Western Clearonox представляет собой 32,5% раствор высокоочищенной мочевины в деминерализованной воде, также известный как AdBlue®. Продукт снижает уровень выбросов оксидов азота (NOx) в выхлопных газах дизельных двигателей. Clearonox производится в Австралии и соответствует или превосходит международный стандарт ISO 22241. Gulf Western Diesel Clearonox может использоваться во всех двигателях, оснащенных системой селективной каталитической нейтрализации (SCR).','10 л.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30180','SUPERTAK CHAIN BAR OIL 1 л. × 8 шт','Gulf Western Oil','special',1650,1100,'Специализированные продукты',NULL,1.0,'л',8,'Масло Gulf Western Supertak Chain Bar Oil защищает шины и цепи высокопроизводительных цепных пил. Содержит противоизносные присадки и добавку для усиления липкости для защиты шины и цепи и минимизации соскакивания цепи. Спецификации:Класс вязкости ISO 150','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30184','LAWN MOWER OIL 30 1 л. × 8 шт','Gulf Western Oil','special',1725,1150,'Специализированные продукты',NULL,1.0,'л',8,'LAWNMOWER OIL — это моторное масло класса SAE 30, предназначенное для картеров небольших 4-тактных бензиновых двигателей. Идеально подходит для тех двигателей, для которых производитель указывает сезонное масло SAE 30. Спецификации: API SJ/CF; SAE 30','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('30193','AIR TOOL 1 л. × 8 шт','Gulf Western Oil','special',1650,1100,'Специализированные продукты',NULL,1.0,'л',8,'Air Tool Oil предназначено для смазки внутренних частей пневматических инструментов, как поршневых, так и роторных. Данное масло противостоит образованию кислот, шлама, лака и ржавчины, которые снижают скорость и мощность инструмента. Предназначено специально для ухода за всеми поршневыми и роторными пневматическими инструментами. Предотвращает образование отложений и ржавчины во время хранения. Обеспечивает адекватную смазку при запуске. Спецификации: КЛАСС ВЯЗКОСТИ ISO 32','1 л. х 8 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('311154','Alpha ENGINE FLUSH - gasoline & diesel engine 0,1 л. × 24 шт','Gulf Western Oil','additive_engine',780,520,'Присадки для двигателя',NULL,0.1,'л',24,'ALPHA ENGINE FLUSH OIL TREATMENT представляет собой смесь растворителей с высокой температурой вспышки и моющих агентов на масляной основе, используемая для полной очистки внутренних деталей двигателя от шлама, смол, ржавчины и лака. Применяется для всех бензиновых, дизельных и газовых двигателей с турбонаддувом или без. Совместим со всеми минеральными, полусинтетическими и полностью синтетическими моторными маслами. Объем 100 мл. предназначен для промывки двигателя мотоцикла.','0,1 л. х 24 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('330194','Alpha ENGINE FLUSH - gasoline & diesel engine 0,3 л. × 24 шт','Gulf Western Oil','additive_engine',960,640,'Присадки для двигателя',NULL,0.3,'л',24,'ALPHA ENGINE FLUSH OIL TREATMENT представляет собой смесь растворителей с высокой температурой вспышки и моющих агентов на масляной основе, используемая для полной очистки внутренних деталей двигателя от шлама, смол, ржавчины и лака. Применяется для всех бензиновых, дизельных и газовых двигателей с турбонаддувом или без. Совместим со всеми минеральными, полусинтетическими и полностью синтетическими моторными маслами. Объем 100 мл. предназначен для промывки двигателя мотоцикла.','0,3 л. х 24 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('330159T','Alpha ENGINE OIL BOOSTER PLUS for GASOLINE & DIEESEL (OIL TREATMENT) 0,946 л. × 12 шт','Gulf Western Oil','additive_engine',3900,2600,'Присадки для двигателя',NULL,0.946,'л',12,'Присадка ALPHA ENGINE BOOSTER повышает рабочие характеристики моторного масла, продлевая срок его службы. Уменьшает трение, износ и выделение голубого выхлопного дыма. Повышает вязкость моторного масла и щелочное число (TBN), восстанавливая компрессию и нейтрализуя вредные кислоты. Формула на основе высококачественных базовых масел, полимеров и синтетических присадок.
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('330159','Alpha ENGINE OIL BOOSTER PLUS for GASOLINE & DIEESEL (OIL TREATMENT) 0,3 л. × 24 шт','Gulf Western Oil','additive_engine',1440,960,'Присадки для двигателя',NULL,0.3,'л',24,'Присадка ALPHA ENGINE BOOSTER повышает рабочие характеристики моторного масла, продлевая срок его службы. Уменьшает трение, износ и выделение голубого выхлопного дыма. Повышает вязкость моторного масла и щелочное число (TBN), восстанавливая компрессию и нейтрализуя вредные кислоты. Формула на основе высококачественных базовых масел, полимеров и синтетических присадок.
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('330158','Alpha STOP SMOKE - gasoline & diesel 0,3 л. × 24 шт','Gulf Western Oil','additive_engine',1110,740,'Присадки для двигателя',NULL,0.3,'л',24,'Alpha STOP SMOKE разработан  для использования в  автомобилях, которые при сжигании топлива образуют много выхлопного дыма и способствуют загрязнению окружающей среды. Продукт основан на комбинации химических полимеров, присадок, улучшающих индекс вязкости. Устраняет/уменьшает выброс выхлопных газов. Способствует более тихой работе двигателя и снижает шумность толкателя.
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('307155','Alpha MCO FUEL INJECTOR CLEANER moto 0,07 л. × 24 шт','Gulf Western Oil','additive_fuel',622,415,'Присадки для топлива',NULL,0.07,'л',24,'Alpha FUEL SYSTEM TREATMENT – многоцелевая присадка для бензина, предназначенная для очистки всей системы подачи топлива, включая клапаны, грязные карбюраторы и засоренные форсунки. Восстанавливает мощность и рабочие характеристики.
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('330157','Alpha FUEL SYSTEM TREATMENT for GASOLINE 0,3 л. × 24 шт','Gulf Western Oil','additive_fuel',1290,860,'Присадки для топлива',NULL,0.3,'л',24,NULL,'0,3 л. х 24 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('330196','Alpha CRDI PLUS 0,3 л. × 24 шт','Gulf Western Oil','additive_fuel',1350,900,'Присадки для топлива',NULL,0.3,'л',24,'Alpha CRDI PLUS эффективно удаляет нагар с форсунок и
INSERT INTO products (article,name,brand,category,price,cost_price,section,viscosity,pack_size,pack_unit,box_qty,specs_text,pack_label,is_active) VALUES ('330234','Alpha PDF PLUS 0,3 л. × 24 шт','Gulf Western Oil','additive_fuel',1650,1100,'Присадки для топлива',NULL,0.3,'л',24,'Alpha DPF PLUS представляет собой металлорганическую присадку к дизельному топливу на основе железа, которая используется в качестве катализатора для регенерации сажевых фильтров. Снижает температуру воспламенения сажи, скопившейся в сажевом фильтре, и оптимизирует периодическое сжигание скопившейся сажи. Уникальное сочетание чистой топливной системы, чистого сгорания с более низким уровнем выбросов и катализируемых частиц сажи очищает и помогает поддерживать чистоту DPF, каталитического нейтрализатора, системы рециркуляции отработавших газов (EGR), а также турбонагнетателя и его лопаток с изменяемой геометрией от отложений.','0,3 л. х 24 шт.',true) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
