обеспечивает полный контроль водителем в сложныхусловиях, комфорт и производительность, дополнительную чистоту, улучшенную экологичность и долговечность. В рецептуре Hybrid Performance используется новейший пакет присадок, разработанный для гибридных силовых агрегатов и обеспечивающий превосходную защиту двигателя от износа в режиме старт-стоп и низкотемпературной коррозии. Продукт также демонстрирует отличную низкотемпературную текучесть и контроль белого осадка и воды. Моторное масло Hybrid Performance создано специально для обеспечения дополнительных эксплуатационных характеристик гибридных двигателей, которые не может предложить традиционное моторное масло. Спецификации: ACEA - C2-21, A5/B5-21 (0W30); ACEA C5-21, C6-21 (0W20); API SP, SN PLUS; API SP RC (0W30); ILSAC GF-6 (0W30); BMW Longlife-12 FE (0W30); MB 227.61, 229.61 (0W30); MB 229.71 (0W20); Ford WSS -M2C950-A (0W30); Ford WSS-M2C952-A1 (0W20); dexos d™ (0W20); OPEL OV0401547 (0W20); STJLR.03.5006 (0W20)','205 л',false) ON CONFLICT (article) DO UPDATE SET name=EXCLUDED.name,price=EXCLUDED.price,cost_price=EXCLUDED.cost_price,category=EXCLUDED.category,section=EXCLUDED.section,viscosity=EXCLUDED.viscosity,pack_size=EXCLUDED.pack_size,pack_unit=EXCLUDED.pack_unit,box_qty=EXCLUDED.box_qty,specs_text=EXCLUDED.specs_text,pack_label=EXCLUDED.pack_label;
